  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) siftDown(nums, i, n);   // 1. build a max-heap
  for (let end = n - 1; end > 0; end--) {
    [nums[0], nums[end]] = [nums[end], nums[0]];   // 2. the largest goes to the end...
