def sift_down(heap, i, n):                     # max-heap: sink below the larger child
    while True:
        left, right = 2 * i + 1, 2 * i + 2
        largest = i
        if left < n and heap[left] > heap[largest]:
            largest = left
        if right < n and heap[right] > heap[largest]:
            largest = right
        if largest == i:
            return
        heap[i], heap[largest] = heap[largest], heap[i]
        i = largest

